7: /** 默认工具展示注册表 */
8: export const DEFAULT_TOOL_REGISTRY: Record<string, ToolDefinition> = {
9:   read_file: {
10:     name: 'read_file',
11:     label: '读取',
12:     icon: FileText,
13:     monoChip: true,
