43: /**
44:  * 将流式思考文本拆分为句子；流式未结束时丢弃未完结的半句。
45:  */
46: function splitSentences(text: string, includePartial: boolean): string[] {
47:   const clean = text.trim().replace(/\s*\n\s*/g, ' ');
48:   if (!clean) return [];
49:   const parts = clean.split(/(?<=[。！？!?；;])\s*/).filter(Boolean);
50:   if (!includePartial && parts.length > 0) {
51:     const last = parts[parts.length - 1];
52:     if (!/[。！？!?；;]$/.test(last)) {
53:       parts.pop();
54:     }
55:   }
56:   return parts;
57: }
58: 
59: function toTraceNodes(
60:   reasoning: string | undefined,
61:   tools: ToolExecution[] | undefined,
62:   elapsedSeconds: number | undefined,
63:   isGenerating: boolean
64: ): TraceNode[] {
65:   const nodes: TraceNode[] = [];
66: 
67:   if (reasoning && reasoning.trim()) {
68:     nodes.push({
69:       type: 'reasoning',
70:       sentences: splitSentences(reasoning, !isGenerating),
71:       durationSeconds: elapsedSeconds,
72:     });
73:   }
74: 
75:   (tools || []).forEach((tool) => {
76:     const running = tool.status === 'running';
77:     const failed = tool.status === 'failed';
78:     const status = running ? 'running' : failed ? 'failed' : 'completed';
79:     // 仅按真实工具名判断是否为终端命令执行，避免把参数 JSON 误判为命令
80:     const isCommand =
81:       tool.toolName === 'execute_command' ||
82:       tool.toolName === 'execute' ||
83:       tool.toolName === 'terminal';
84:     const toolDef = DEFAULT_TOOL_REGISTRY[tool.toolName];
85:     const toolLabel = typeof toolDef?.label === 'function' ? toolDef.label(undefined) : toolDef?.label;
86: 
87:     if (isCommand) {
88:       nodes.push({
89:         id: tool.toolCallId,
90:         type: 'terminal',
91:         toolName: tool.toolName,
92:         primary: '运行',
93:         secondary: tool.command,
94:         command: tool.command,
95:         output: tool.output,
96:         exitCode: failed ? 1 : 0,
97:         status,
98:       });
99:       return;
100:     }
101: 
102:     nodes.push({
103:       id: tool.toolCallId,
104:       type: 'tool',
105:       toolName: tool.toolName,
106:       primary: toolLabel || tool.toolName,
107:       secondary: tool.command || tool.toolName,
108:       command: tool.command,
109:       status,
110:       details: tool.output
111:         ? tool.output
112:             .split('\n')
113:             .filter(Boolean)
114:             .map((text) => ({ text, tone: 'muted' as const }))
115:         : undefined,
116:     });
117:   });
118: 
119:   return nodes;
120: }
121: 
122: export interface AgentResponseProps {
123:   msg: ChatMessage;
124:   isGenerating: boolean;
125:   elapsedSeconds?: number;
126: }
127: 
128: /**
129:  * Agent 响应过程区：由 ChatMessage 构建时间线（思考 + 工具/终端），
130:  * 并以“工作中 → 共耗时 N 秒”的折叠态呈现。
131:  */
132: export const AgentResponse: React.FC<AgentResponseProps> = ({
133:   msg,
134:   isGenerating,
135:   elapsedSeconds,
136: }) => {
137:   const trace = useMemo(
138:     () => toTraceNodes(msg.reasoning, msg.tools, elapsedSeconds, isGenerating),
139:     [msg.reasoning, msg.tools, elapsedSeconds, isGenerating]
140:   );
141: 
142:   if (!isGenerating && trace.length === 0) return null;
143: 
144:   return (
145:     <div className={styles.container}>
146:       <ThinkingState
147:         nodes={trace}
148:         tools={DEFAULT_TOOL_REGISTRY}
149:         isWorking={isGenerating}
150:         elapsedSeconds={elapsedSeconds}
151:         workingLabel="正在处理"
152:       />
153:     </div>
154:   );
155: };

