30: export interface ThinkingStateProps {
31:   nodes?: TraceNode[];
32:   tools?: Record<string, ToolDefinition>;
33:   isWorking: boolean;
34:   elapsedSeconds?: number;
35:   workingLabel?: string;
36:   defaultExpanded?: boolean;
37: }
38: 
39: /**
40:  * 思考状态总控：实时事件驱动的“工作中 → 共耗时 N 秒”折叠时间线。
41:  */
42: export const ThinkingState: React.FC<ThinkingStateProps> = ({
43:   nodes = [],
44:   tools = {},
45:   isWorking,
46:   elapsedSeconds = 0,
47:   workingLabel = '正在处理',
48:   defaultExpanded,
49: }) => {
50:   const [manualExpanded, setManualExpanded] = useState<boolean | null>(
51:     defaultExpanded !== undefined ? defaultExpanded : null
52:   );
53: 
54:   const activeIndex = isWorking ? nodes.length - 1 : nodes.length;
55:   const isGlobalExpanded = manualExpanded !== null ? manualExpanded : isWorking;
56: 
57:   if (nodes.length === 0 && !isWorking) return null;
58: 
59:   return (
60:     <div className={styles.container}>
61:       <button
62:         type="button"
63:         aria-expanded={isGlobalExpanded}
64:         onClick={() => setManualExpanded((prev) => !(prev !== null ? prev : isWorking))}
65:         className={styles.masterTrigger}
66:       >
67:         {isWorking && <PixelDotsLoader />}
68: 
69:         <span className={styles.masterLabel}>
70:           {isWorking ? (
71:             <span className={styles.workingShimmer}>{workingLabel}</span>
72:           ) : (
73:             <>
74:               共耗时 <span className={styles.elapsed}>{elapsedSeconds}</span> 秒
75:             </>
76:           )}
77:         </span>
78: 
79:         <ChevronDown
80:           aria-hidden="true"
81:           className={`${styles.chevron} ${isGlobalExpanded ? styles.chevronOpen : ''}`}
82:         />
83:       </button>
84: 
85:       <div className={`${styles.channel} ${isGlobalExpanded ? styles.channelOpen : ''}`}>
86:         <div className={styles.channelInner}>
87:           <div className={styles.timeline}>
88:             {nodes.map((node, idx) => {
89:               const nodeRunning = node.status === 'running' || node.status === 'pending';
90:               const isNodeActive =
91:                 node.type === 'reasoning'
92:                   ? isWorking && idx === activeIndex
93:                   : isWorking && nodeRunning;
94:               const isNodeFinished =
95:                 node.type === 'reasoning'
96:                   ? !isWorking || idx < activeIndex
97:                   : !isWorking || !nodeRunning;
98: 
99:               if (node.type === 'reasoning' && node.sentences) {
100:                 return (
101:                   <NestedReasoningBlock
102:                     key={node.id || idx}
103:                     sentences={node.sentences}
104:                     isActive={isNodeActive}
105:                     isFinished={isNodeFinished}
106:                     durationSeconds={node.durationSeconds}
107:                   />
108:                 );
109:               }
110: 
111:               if (node.type === 'tool' || node.type === 'terminal' || node.type === 'search') {
112:                 return (
113:                   <ToolCall
114:                     key={node.id || idx}
115:                     {...toolNodeToToolCallProps(node)}
116:                   />
117:                 );
118:               }
119: 
120:               return (
121:                 <TracePillRow
122:                   key={node.id || idx}
123:                   node={node}
124:                   isActive={isNodeActive}
125:                   isFinished={isNodeFinished}
126:                   toolRegistry={tools}
127:                 />
128:               );
129:             })}
130:           </div>
131:         </div>
132:       </div>
133:     </div>
134:   );
135: };

