7: /** 将毫秒时间戳格式化为本地日期时间（精确到秒）：YYYY-MM-DD HH:mm:ss。 */
8: export function formatMessageTimestampSeconds(timestamp: number): string {
9:   if (!Number.isFinite(timestamp) || timestamp <= 0) return '';
10:   const date = new Date(timestamp);
11:   if (Number.isNaN(date.getTime())) return '';
12:   return `${date.getFullYear()}-${padTwo(date.getMonth() + 1)}-${padTwo(date.getDate())} `
13:     + `${padTwo(date.getHours())}:${padTwo(date.getMinutes())}:${padTwo(date.getSeconds())}`;
14: }
