16: /**
17:  * 判断一条历史/后端消息是否属于 Agent 主动推送消息。
18:  * 优先认服务端显式 proactive 标记；旧记录缺少该字段时，按“无同轮 USER 消息且无模型耗时/用量”识别。
19:  */
20: export function isProactiveTranscriptMessage(
21:   dto: TranscriptMessageDto,
22:   userTurnIds?: Set<string> | TranscriptMessageDto[],
23: ): boolean {
24:   if (dto.role?.toUpperCase() !== 'ASSISTANT') return false;
25:   if (dto.proactive === true) return true;
26:   if (dto.proactive === false && !userTurnIds) return false;
27:   if (!dto.turnId || dto.status !== 'COMPLETED') return false;
28:   if ((dto.durationMillis ?? 0) !== 0 || dto.usage || dto.thinking) return false;
29:   if (dto.tools && dto.tools.length > 0) return false;
30:   if (!userTurnIds) return false;
31:   if (userTurnIds instanceof Set) {
32:     return !userTurnIds.has(dto.turnId);
33:   }
34:   return !userTurnIds.some((item) => item.role?.toUpperCase() === 'USER' && item.turnId === dto.turnId);
35: }
36: 
37: export function mapTranscriptToChatMessage(
38:   dto: TranscriptMessageDto,
39:   _index?: number,
40:   allMessages?: TranscriptMessageDto[],
41:   userTurnIds?: Set<string>,
42: ): ChatMessage {
43:   const isUser = dto.role?.toUpperCase() === 'USER';
44:   const proactive = isUser ? false : isProactiveTranscriptMessage(dto, userTurnIds ?? allMessages);
45:   const parsedTime = dto.createdAt ? new Date(dto.createdAt).getTime() : NaN;
46:   const createdAt = Number.isFinite(parsedTime) && parsedTime > 0
47:     ? parsedTime
48:     : (proactive ? 0 : Date.now());
49:   return {
50:     id: dto.id,
51:     turnId: dto.turnId,
52:     role: isUser ? 'user' : 'assistant',
53:     modelName: isUser ? undefined : 'ButvanAgent',
54:     content: dto.content || '',
55:     reasoning: dto.thinking || undefined,
56:     createdAt,
57:     status: dto.status,
58:     usage: dto.usage,
59:     proactive: proactive || undefined,
60:     elapsedTime:
61:       dto.durationMillis != null
62:         ? Math.max(1, Math.round(dto.durationMillis / 1000))
63:         : undefined,
64:     tools:
65:       dto.tools && dto.tools.length > 0
66:         ? dto.tools.map((t) => ({
67:             toolCallId: t.toolCallId,
68:             toolName: t.toolName,
69:             command: t.command,
70:             output: t.output,
71:             status: (t.status ? t.status.toLowerCase() : 'completed') as
72:               | 'running'
73:               | 'completed'
74:               | 'failed'
75:               | 'cancelled',
76:           }))
77:         : undefined,
78:   };
79: }
80: 
81: /** 批量映射整段会话记录，一次建立用户轮次索引以 O(n) 识别历史主动推送消息。 */
82: export function mapTranscriptMessages(dtos: TranscriptMessageDto[]): ChatMessage[] {
83:   const userTurnIds = new Set<string>();
84:   for (const dto of dtos) {
85:     if (dto.role?.toUpperCase() === 'USER' && dto.turnId) {
86:       userTurnIds.add(dto.turnId);
87:     }
88:   }
89:   return dtos.map((dto, index) => mapTranscriptToChatMessage(dto, index, dtos, userTurnIds));
90: }

