191:         } else if (event instanceof AgentStreamEvent.ToolCall toolCall) {
192:             recordToolCall(toolCall);
193: 
194:             // 工具结果返回：追加输出并按事件中的真实状态更新
195:         } else if (event instanceof AgentStreamEvent.ToolResult toolResult) {
196:             recordToResult(toolResult);
