200:     private void recordToResult(AgentStreamEvent.ToolResult toolResult) {
201:         // 追加本次结果输出；command 沿用之前已记录的值
202:         toolExecutions.compute(toolResult.toolCallId(), (key, previous) ->
203:                 new TranscriptMessageDto.ToolExecutionDto(
204:                         toolResult.toolCallId(),
205:                         toolResult.toolName(),
206:                         previous == null ? "" : previous.command(),
207:                         (previous == null ? "" : previous.output()) + toolResult.result(),
208:                         switch (toolResult.status()) {
209:                             case RUNNING -> TranscriptMessageDto.ToolStatus.RUNNING;
210:                             case COMPLETED -> TranscriptMessageDto.ToolStatus.COMPLETED;
211:                             case FAILED -> TranscriptMessageDto.ToolStatus.FAILED;
212:                             case CANCELLED -> TranscriptMessageDto.ToolStatus.CANCELLED;
213:                         }
214:                 ));
215:     }
