217:     private void recordToolCall(AgentStreamEvent.ToolCall toolCall) {
218:         // 同一 callId 只保留一条记录；command 为空时沿用上一次的值
219:         toolExecutions.compute(toolCall.toolCallId(), (key, previous) ->
220:                 new TranscriptMessageDto.ToolExecutionDto(
221:                         toolCall.toolCallId(),
222:                         toolCall.toolName(),
223:                         toolCall.command().isBlank() && previous != null ? previous.command() : toolCall.command(),
224:                         previous == null ? "" : previous.output(),
225:                         TranscriptMessageDto.ToolStatus.RUNNING // 工具尚未返回结果
226:                 ));
227:     }
