238:         TranscriptMessageDto.ToolStatus fallbackStatus = switch (messageStatus) {
239:             case COMPLETED, FAILED -> TranscriptMessageDto.ToolStatus.FAILED;
240:             case CANCELLED -> TranscriptMessageDto.ToolStatus.CANCELLED;
241:         };
242:         // 只把任处于 RUNNING 的记录改为兜底状态，其余原样保留
243:         return toolExecutions.values().stream()
244:                 .map(tool -> tool.status() == TranscriptMessageDto.ToolStatus.RUNNING
245:                         ? new TranscriptMessageDto.ToolExecutionDto(
246:                                 tool.toolCallId(), tool.toolName(), tool.command(), tool.output(), fallbackStatus
247:                         ) : tool
248:                 ).toList();
249:     }
