34:     /**
35:      * 结束一次运行并落库
36:      * @param run
37:      * @param status
38:      */
39:     public void complete(AgentRun run, TranscriptMessageDto.MessageStatus status) {
40:         // 取消路径通常先中断生产线程；清掉本次中断标记，避免 Files.lines 等可中断 I/O
41:         // 在读取 transcript 时抛出 ClosedByInterruptException。收尾完成后恢复原标记。
42:         boolean interrupted = Thread.interrupted();
43:         try {
44:             completeInternal(run, status);
45:         } finally {
46:             if (interrupted) Thread.currentThread().interrupt();
47:         }
48:     }
49: 
50:     /**
51:      * 尝试写入终态，避免存储故障逃出异步生产线程。
52:      *
53:      * @return transcript 已存在或本次成功写入时返回 {@code true}
54:      */
55:     public boolean tryComplete(AgentRun run, TranscriptMessageDto.MessageStatus status) {
56:         try {
57:             complete(run, status);
58:             return true;
59:         } catch (RuntimeException exception) {
60:             log.error("Agent 终态持久化失败：sessionId={}, turnId={}, status={}",
61:                     run.sessionId(), run.turnId(), status, exception);
62:             return false;
63:         }
64:     }
65: 
66:     private void completeInternal(AgentRun run, TranscriptMessageDto.MessageStatus status) {
67:         if (!run.beginCompletion()) return;
68: 
69:         // 防止系统时钟微笑回拨产生负数
70:         long durationMillis = Math.max(0, Duration.between(run.startedAt(), Instant.now()).toMillis());
71: 
72:         try {
73:             // 固化工具状态并落库完整 assistant 消息
74:             transcriptService.appendAssistantMessage(
75:                     run.sessionId(),
76:                     run.turnId(),
77:                     run.contentAsString(),
78:                     run.thinkingAsString(),
79:                     status,
80:                     durationMillis,
81:                     run.finalizeTools(status),
82:                     run.tokenUsage()
83:             );
84:             run.commitCompletion(status);
85:         } catch (RuntimeException exception) {
86:             run.abortCompletion();
87:             throw exception;
88:         }
89: 
90:         try { memoryLifecycle.completed(run.userId(), run.sessionId(), run.turnId(), status); }
91:         catch (RuntimeException exception) {
92:             log.warn("经历任务通知未完成，保留补偿资格：errorType={}", exception.getClass().getSimpleName());
93:         }
94: 
95:         try {
96:             checkpointService.delete(run.turnId());
97:         } catch (RuntimeException exception) {
98:             // transcript 已是权威终态；遗留检查点会在下次启动时按 turnId 去重并清理。
99:             log.warn("清理已完成 Agent 运行检查点失败：turnId={}", run.turnId(), exception);
100:         }
101: 
102:         // transcript 已是权威终态；目录册预览刷新失败不能推翻已完成状态。
103:         try {
104:             sessionCatalogService.touch(run.sessionId(), run.contentAsString());
105:         } catch (RuntimeException exception) {
106:             log.warn("刷新已完成 Agent 运行的会话摘要失败：sessionId={}, turnId={}",
107:                     run.sessionId(), run.turnId(), exception);
108:         }
109:     }
110: }

