41:             return;
42:         }
43: 
44:         try {
45:             if (!transcriptService.hasAssistantMessage(checkpoint.sessionId(), checkpoint.turnId())) {
46:                 long durationMillis = Math.max(0L, Duration.between(
47:                         checkpoint.startedAt(), checkpoint.updatedAt()).toMillis());
48:                 transcriptService.appendAssistantMessage(
49:                         checkpoint.sessionId(),
50:                         checkpoint.turnId(),
51:                         checkpoint.content(),
52:                         checkpoint.thinking(),
53:                         TranscriptMessageDto.MessageStatus.CANCELLED,
54:                         durationMillis,
55:                         checkpoint.tools(),
56:                         checkpoint.usage()
57:                 );
58:                 sessionCatalogService.touch(checkpoint.sessionId(), checkpoint.content());
59:             }
