305:      * @param run
306:      * @param inputMessages
307:      * @param streamSession
308:      */
309:     private void runAgentStream(AgentRun run, List<Msg> inputMessages, AgentStreamSession streamSession) {
310:         HarnessAgent agent = agentFactory.currentAgent(run.sessionId());
311:         streamSession.bindCancellationAction(
312:                 () -> agent.getDelegate().interrupt(run.userId(), run.sessionId()));
313:         ModelIdentity modelIdentity = currentModelIdentity();
314:         SessionPermissionMode productMode = sessionCatalogService.getPermissionMode(run.sessionId());
315:         agent.getDelegate().getAgentState(run.userId(), run.sessionId())
316:                 .setPermissionContext(agentSecurity.createPermissionContext(productMode));
317:         // setPermissionMode 同时重建当前会话的权限引擎并持久化新的上下文。
318:         agent.setPermissionMode(run.userId(), run.sessionId(), toAgentScopeMode(productMode));
319: 
320:         for (AgentEvent event : agent.streamEvents(inputMessages,
321:                 run.runtimeContext()).toIterable()) {
322:             // Token usage 必须在 UI 映射之前采集，包含工具循环和子 Agent 原始事件。
323:             run.recordModelEvent(event, modelIdentity);
324: 
325:             // 客户端断开：立即按取消收尾
326:             if (streamSession.isCancelled()) {
327:                 finishCancelled(run, streamSession);
328:                 return;
329:             }
330: 
331:             // 必须在普通映射之前识别该事件
332:             if (event instanceof RequireUserConfirmEvent confirmEvent) {
333:                 if (pauseForConfirmation(run, confirmEvent.getToolCalls(), streamSession)) {
334:                     return;
335:                 }
336:                 continue;
337:             }
338: 
339:             AgentStreamEvent mapped = agentEventManager.map(event, run.toolArgsBuffer(), run.toolResultPrefixBuffer());
340:             run.record(mapped);
341:             if (event instanceof ModelCallEndEvent) {
342:                 checkpointService.save(run);
343:             }
344:             if (mapped != null && mapped.isTerminal()) {
345:                 // 先持久化再发送终态，确保前端收到 done 后能立即读取完整消息与 usage。
346:                 if (agentRunCompleter.tryComplete(run, TranscriptMessageDto.MessageStatus.COMPLETED)) {
347:                     profileMaintenanceScheduler.consider(run.userId());
348:                     putEvent(streamSession, mapped);
349:                 } else {
350:                     putEvent(streamSession,
351:                             new AgentStreamEvent.Failed(terminalPersistenceFailureMessage(false)));
352:                 }
353:                 return;
354:             }
355:             if (mapped != null && !putEvent(streamSession, mapped)) {
356:                 finishCancelled(run, streamSession);
357:                 return;
358:             }
359:         }
360: 
361:         if (streamSession.isCancelled()) {
362:             finishCancelled(run, streamSession);
363:             return;
364:         }
365: 
366:         // 事件流自然结束：正常收尾
367:         if (agentRunCompleter.tryComplete(run, TranscriptMessageDto.MessageStatus.COMPLETED)) {
368:             profileMaintenanceScheduler.consider(run.userId());
369:             putEvent(streamSession, new AgentStreamEvent.Completed());
370:         } else {
371:             putEvent(streamSession,
372:                     new AgentStreamEvent.Failed(terminalPersistenceFailureMessage(false)));
373:         }
374:     }
