392:     private boolean pauseForConfirmation(AgentRun run, List<ToolUseBlock> askedTools, AgentStreamSession streamSession) {
393:         List<ConfirmResult> rememberResults = new ArrayList<>();
394:         List<ToolUseBlock> unresolved = new ArrayList<>();
395: 
396:         for (ToolUseBlock tool : askedTools) {
397:             Optional<Boolean> remembered = pendingApprovalStore.remembered(
398:                     run.userId(),
399:                     run.sessionId(),
400:                     tool
401:             );
402:             if (remembered.isPresent()) {
403:                 // 已记住也要走 ConfirmResult，不能跳过 AgentScope 的状态恢复流程
404:                 rememberResults.add(new ConfirmResult(remembered.get(), tool));
405:             } else {
406:                 unresolved.add(tool);
407:             }
408:         }
409: 
410:         if (unresolved.isEmpty()) {
