9: 
10: function formatTime(timestamp: number): string {
11:   try {
12:     return new Date(timestamp).toLocaleTimeString('zh-CN', {
13:       hour: '2-digit',
14:       minute: '2-digit',
15:     });
16:   } catch {
17:     return '';
18:   }
19: }
20: 
21: interface BuildResult {
22:   chapters: StepRailChapter[];
23:   currentIndex: number;
24: }
25: 
26: /**
27:  * 从消息流中提取对话章节：一个来回（用户提问 + Agent 回复）算一个节点，
28:  * 标题取用户提问内容，内容区取 Agent 最终回复；工具调用等内部过程不进入时间轨。
29:  */
30: function buildChapters(messages: ChatMessage[]): BuildResult | null {
31:   const chapters: StepRailChapter[] = [];
32: 
33:   for (let i = 0; i < messages.length; i++) {
34:     if (messages[i].role !== 'user') continue;
35:     const user = messages[i];
36: 
37:     // 查找该提问之后的第一条 Agent 回复
38:     let assistant: ChatMessage | undefined;
39:     for (let j = i + 1; j < messages.length; j++) {
40:       if (messages[j].role === 'assistant') {
41:         assistant = messages[j];
42:         break;
43:       }
44:     }
45: 
46:     if (!assistant) {
47:       // 最后一条提问尚无回复：视为进行中
48:       chapters.push({
49:         id: `turn-pending-${user.id}`,
50:         title: user.content || '对话',
51:         description: 'Agent 正在处理…',
52:         meta: '…',
53:         messageId: user.id,
54:       });
55:       continue;
56:     }
57: 
58:     const isGenerating =
59:       assistant.status === undefined && assistant.elapsedTime === undefined;
60:     const replyText = assistant.content || (isGenerating ? 'Agent 正在处理…' : '');
61:     if (!replyText) continue; // 跳过既无正文也未在生成的旧回复
62: 
63:     chapters.push({
64:       id: `turn-${user.id}`,
65:       title: user.content || '对话',
66:       description: replyText,
67:       meta: formatTime(user.createdAt),
68:       messageId: assistant.id,
69:     });
70:   }
71: 
72:   if (chapters.length === 0) return null;
73: 
74:   // 当前位置始终指向最近一次对话
75:   const currentIndex = Math.max(0, chapters.length - 1);
76:   return { chapters, currentIndex };
77: }
78: 
79: export interface ChatStepRailProps {
80:   messages: ChatMessage[];
81:   onSelect?: (chapter: StepRailChapter) => void;
82: }
83: 
84: /**
85:  * 聊天内容左侧的 Codex 风格任务步骤时间轨。
86:  */
87: export const ChatStepRail: React.FC<ChatStepRailProps> = ({
88:   messages,
89:   onSelect,
90: }) => {
91:   const built = useMemo(() => buildChapters(messages), [messages]);
92: 
93:   if (!built) return null;
94: 
95:   return (
96:     <ChapterScrubber
97:       chapters={built.chapters}
98:       currentIndex={built.currentIndex}
99:       side="right"
100:       label="当前任务步骤"
101:       onSelect={(chapter) => {
102:         const railChapter = chapter as StepRailChapter;
103:         onSelect?.(railChapter);
104:       }}
105:     />
106:   );
107: };
108: 
109: export default ChatStepRail;

