450:  * 利用 fetch + ReadableStream 实时解析后端推流
451:  */
452: export async function streamAgentChat(
453:   params: {
454:     runId: string;
455:     sessionId: string;
456:     content?: string;
457:     context?: string;
458:     recordReferenceIds?: string[];
459:     analysisContext?: AgentAnalysisContextRequest;
460:     /** 随本轮一次性提交的图片（Base64，不含 data URL 前缀）。 */
461:     images?: { mediaType: string; dataBase64: string }[];
462:     approvalId?: string;
463:     signal?: AbortSignal;
464:   },
465:   onChunk: (text: string) => void,
466:   onComplete?: () => void,
467:   onError?: (error: Error) => void,
468:   onToolCall?: (payload: ToolCallPayload) => void,
469:   onToolResult?: (payload: ToolResultPayload) => void,
470:   onThinking?: (thinkingText: string) => void,
471:   onPermissionRequired?: (payload: PermissionRequiredPayload) => void,
472:   onSubagentProgress?: (payload: SubagentProgressDto) => void,
473:   onCancelled?: () => void,
474:   onRoutingNotice?: (payload: RoutingNoticePayload) => void,
475: ): Promise<void> {
476:   try {
477:     const payloadContent = params.content || params.context || '';
478:     const modelContext = params.context || params.content || '';
479:     const isResume = Boolean(params.approvalId);
480:     const response = await apiFetch(
481:       `${apiBaseUrl}/agent/chat${isResume ? '/permission/resume' : '/stream'}`,
482:       {
483:       method: 'POST',
484:       headers: {
485:         'Content-Type': 'application/json',
486:       },
487:         signal: params.signal,
488:         body: JSON.stringify(isResume
489:           ? { sessionId: params.sessionId, approvalId: params.approvalId, runId: params.runId }
490:           : {
491:               runId: params.runId,
492:               sessionId: params.sessionId,
493:               context: modelContext,
494:               content: payloadContent,
495:               recordReferenceIds: params.recordReferenceIds ?? [],
496:               analysisContext: params.analysisContext,
497:               images: params.images ?? [],
498:             }),
499:       }
500:     );
501: 
502:     await assertChatStreamResponse(response);
503: 
504:     if (!response.body) {
505:       throw new Error('ReadableStream 不可用');
506:     }
507: 
508:     const reader = response.body.getReader();
509:     const decoder = new TextDecoder('utf-8');
510:     let buffer = '';
511: 
512:     let streamFinished = false;
513: 
514:     const dispatchSseEvent = (eventBlock: string) => {
515:       let eventName = 'message';
516:       const dataLines: string[] = [];
517: 
518:       for (const rawLine of eventBlock.split(/\r?\n/)) {
519:         if (rawLine.startsWith('event:')) {
520:           eventName = rawLine.substring(6).trim();
521:         } else if (rawLine.startsWith('data:')) {
522:           dataLines.push(rawLine.substring(5).trimStart());
523:         }
524:       }
525: 
526:       const dataStr = dataLines.join('\n');
527:       if (eventName === 'text' || eventName === 'message') {
528:         if (dataStr) onChunk(dataStr);
529:       } else if (eventName === 'thinking') {
530:         if (dataStr) onThinking?.(dataStr);
531:       } else if (eventName === 'tool_call') {
532:         try {
533:           const payload: ToolCallPayload = JSON.parse(dataStr);
534:           onToolCall?.(payload);
535:         } catch {
536:           onToolCall?.({ toolName: 'tool', command: dataStr });
537:         }
538:       } else if (eventName === 'tool_result') {
539:         try {
540:           const payload: ToolResultPayload = JSON.parse(dataStr);
541:           onToolResult?.(payload);
542:         } catch {
543:           onToolResult?.({ toolName: 'tool', result: dataStr });
544:         }
545:       } else if (eventName === 'permission_required') {
546:         streamFinished = true;
547:         try {
548:           onPermissionRequired?.(JSON.parse(dataStr) as PermissionRequiredPayload);
549:         } catch {
550:           onError?.(new Error('权限确认事件格式错误'));
551:         }
552:       } else if (eventName === 'subagent') {
553:         try {
554:           const payload: unknown = JSON.parse(dataStr);
555:           if (!isSubagentProgressDto(payload)) throw new Error('invalid payload');
556:           onSubagentProgress?.(payload);
557:         } catch {
558:           onError?.(new Error('子 Agent 进度事件格式错误'));
559:         }
560:       } else if (eventName === 'routing_notice') {
561:         try {
562:           const payload = JSON.parse(dataStr) as RoutingNoticePayload;
563:           if (typeof payload.code !== 'string' || typeof payload.message !== 'string') {
564:             throw new Error('invalid payload');
565:           }
566:           onRoutingNotice?.({
567:             code: payload.code,
568:             message: payload.message,
569:             requestId: typeof payload.requestId === 'string' ? payload.requestId : '',
570:             retryable: payload.retryable === true,
571:             retryAfterMillis: typeof payload.retryAfterMillis === 'number'
572:               ? payload.retryAfterMillis
573:               : null,
574:           });
575:         } catch {
576:           console.warn('Jev 路由提示事件格式错误');
577:         }
578:       } else if (eventName === 'error') {
579:         streamFinished = true;
580:         onError?.(new Error(dataStr || 'Agent 流式处理失败'));
581:       } else if (eventName === 'cancelled') {
582:         streamFinished = true;
583:         onCancelled?.();
584:       } else if (eventName === 'done') {
585:         streamFinished = true;
586:         onComplete?.();
587:       }
588:     };
589: 
590:     while (true) {
591:       const { done, value } = await reader.read();
592:       if (done) {
593:         buffer += decoder.decode();
594:         if (buffer.trim()) dispatchSseEvent(buffer);
595:         if (!streamFinished) {
596:           onError?.(new Error('Agent 流连接意外结束，未收到终态，请重试。'));
597:         }
598:         break;
599:       }
600: 
601:       buffer += decoder.decode(value, { stream: true });
602:       const eventBlocks = buffer.split(/\r?\n\r?\n/);
603:       buffer = eventBlocks.pop() || ''; // 保留尚未接收完整的 SSE 事件。
604: 
605:       for (const eventBlock of eventBlocks) {
606:         if (eventBlock.trim()) dispatchSseEvent(eventBlock);
607:       }
608:     }
609:   } catch (error: unknown) {
610:     if (error instanceof DOMException && error.name === 'AbortError') return;
611:     console.error('SSE 流数据解析失败:', error);
612:     onError?.(error instanceof Error ? error : new Error('SSE 流数据解析失败'));
613:   }
614: }
