import React, { useMemo, useState } from 'react';
import { AlertCircle, ChevronDown, Layers, Loader2 } from 'lucide-react';
import type { ToolExecution, TraceNode } from '../../types/chat';
import { formatToolGroupSummary } from '../../features/chat/messageBlocks';
import { ToolCall, toolNodeToToolCallProps } from './ToolCall';
import styles from './ToolGroupBlock.module.css';

export interface ToolGroupBlockProps {
  tools: ToolExecution[];
  isGenerating: boolean;
  defaultOpen?: boolean;
  resolveToolLabel?: (toolName: string) => string | undefined;
}

/** 将单个运行期 ToolExecution 转为通用 TraceNode，供 ToolCall 卡片复用。 */
export function toolExecutionToTraceNode(
  tool: ToolExecution,
  resolveToolLabel?: (toolName: string) => string | undefined,
): TraceNode {
  const running = tool.status === 'running';
  const failed = tool.status === 'failed';
  const status = running ? 'running' : failed ? 'failed' : 'completed';
  const isCommand =
    tool.toolName === 'execute_command' ||
    tool.toolName === 'execute' ||
    tool.toolName === 'terminal';

  if (isCommand) {
    return {
      id: tool.toolCallId,
      type: 'terminal',
      toolName: tool.toolName,
      primary: '运行',
      secondary: tool.command,
      command: tool.command,
      output: tool.output,
      exitCode: failed ? 1 : 0,
      status,
    };
  }

  const label = resolveToolLabel?.(tool.toolName);
  return {
    id: tool.toolCallId,
    type: 'tool',
    toolName: tool.toolName,
    primary: label || tool.toolName,
    secondary: tool.command || tool.toolName,
    command: tool.command,
    status,
    details: tool.output
      ? tool.output
          .split('\n')
          .filter(Boolean)
          .map((text) => ({ text, tone: (failed ? 'error' : 'muted') as 'error' | 'muted' }))
      : undefined,
  };
}

/**
 * 步进式工具组折叠条：默认收起为单行操作摘要（如“已网页搜索（6 次）”），点击展开查看各工具详情。
 */
export const ToolGroupBlock: React.FC<ToolGroupBlockProps> = ({
  tools,
  isGenerating,
  defaultOpen = false,
  resolveToolLabel,
}) => {
  const [open, setOpen] = useState(defaultOpen);
  const summary = useMemo(
    () => formatToolGroupSummary(tools, isGenerating),
    [tools, isGenerating],
  );

  if (tools.length === 0) return null;

  return (
    <div className={styles.container}>
      <button
        type="button"
        className={styles.trigger}
        aria-expanded={open}
        onClick={() => setOpen((prev) => !prev)}
      >
        <span className={styles.iconWrap}>
          {summary.running ? (
            <Loader2 size={14} className={styles.spinner} aria-hidden="true" />
          ) : summary.failedCount > 0 ? (
            <AlertCircle size={14} className={styles.failedIcon} aria-hidden="true" />
          ) : (
            <Layers size={14} className={styles.doneIcon} aria-hidden="true" />
          )}
        </span>

        <span className={`${styles.label} ${summary.running ? styles.runningShimmer : ''}`}>
          {summary.label}
        </span>

        <ChevronDown
          size={13}
          aria-hidden="true"
          className={`${styles.chevron} ${open ? styles.chevronOpen : ''}`}
        />
      </button>

      <div className={`${styles.channel} ${open ? styles.channelOpen : ''}`}>
        <div className={styles.channelInner}>
          <div className={styles.list}>
            {tools.map((tool, index) => (
              <ToolCall
                key={tool.toolCallId || index}
                {...toolNodeToToolCallProps(toolExecutionToTraceNode(tool, resolveToolLabel))}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

.container {
  display: flex;
  width: 100%;
  flex-direction: column;
  margin: 2px 0;
}

.trigger {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  align-items: center;
  gap: 7px;
  padding: 4px 8px 4px 4px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  text-align: left;
  font-size: 13px;
  line-height: 1.45;
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.trigger:hover {
  background: var(--bg-surface);
  color: var(--text-primary);
}

.iconWrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.doneIcon {
  color: var(--text-muted);
  opacity: 0.8;
}

.failedIcon {
  color: #e11d48;
}

.spinner {
  color: var(--text-secondary);
  animation: spin 0.9s linear infinite;
}

.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 450;
}

.runningShimmer {
  font-weight: 500;
  color: transparent;
  background-image: linear-gradient(
    90deg,
    var(--text-muted) 35%,
    var(--text-primary) 50%,
    var(--text-muted) 65%
  );
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  animation: shimmer 1.5s linear infinite;
}

.chevron {
  flex-shrink: 0;
  opacity: 0.45;
  transition: transform 200ms ease, opacity 150ms ease;
}

.trigger:hover .chevron {
  opacity: 0.9;
}

.chevronOpen {
  opacity: 0.9;
  transform: rotate(180deg);
}

.channel {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
  transition: grid-template-rows 240ms ease-out, opacity 240ms ease-out;
}

.channelOpen {
  grid-template-rows: 1fr;
  opacity: 1;
  pointer-events: auto;
}

.channelInner {
  min-height: 0;
  overflow: hidden;
}

.list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 4px 0 4px 8px;
  padding: 2px 0 2px 10px;
  border-left: 1px solid var(--border-medium);
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

